  options = options || {};
  const rule = rules.get(ruleName);
  if (!rule) {
    return { valid: false, error: `Validation rule "${ruleName}" not found` };
  }
  const result = rule.fn(value);
  if (!result) {
    return { valid: false, error: options.message || rule.errorMessage };
  }
